const j = $input.first().json;
const body = j.body || j;
const message = (body.message || body.text || body.payload || j.message || '').toString().trim();
if (!message) {
  return [{ json: { ok: false, error: 'message fehlt' } }];
}
const tenant = (body.kunde_id || body.tenant_id || body.tenant || 'AGENCY').toString();
return [{ json: { message, source: body.source || 'n8n-webhook', kunde_id: tenant, redact: true } }];

const r = $input.first().json;
const agents = r.mitarbeiter || r.target_agents || [];
return [{
  json: {
    ok: !!r.ok,
    tenant_id: r.tenant_id || 'AGENCY',
    mitarbeiter: agents,
    target_agents: agents,
    prioritaet: r.prioritaet || 'normal',
    payload: r.payload || '',
    ziel: r.ziel || '',
    context: r.context || '',
    playbook: r.playbook || '',
    cursor_briefings: r.cursor_briefings || [],
    security: r.security || {},
    audit_id: r.audit_id || null,
    pii_flags: r.pii_flags || {},
    dispatches: agents.map(a => ({ agent: a, status: 'routed', next: 'Cursor Skill oder Sub-Workflow' })),
    note: 'PII in Response redigiert. Kein Klartext-Logging von Kundendaten in n8n noetig. Hosting: Nuernberg.'
  }
}];
